CREATE DATABASE IF NOT EXISTS lokalph CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lokalph;
CREATE TABLE roles(id TINYINT PRIMARY KEY, name VARCHAR(20) UNIQUE NOT NULL);
INSERT INTO roles VALUES(1,'customer'),(2,'owner'),(3,'admin');
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, role_id TINYINT NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, phone VARCHAR(30), active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE business_categories(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE product_categories(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE businesses(id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, category_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, phone VARCHAR(30), facebook VARCHAR(255), logo VARCHAR(255), cover VARCHAR(255),
  status ENUM('pending','approved','rejected') DEFAULT 'pending', verified TINYINT(1) DEFAULT 0, featured TINYINT(1) DEFAULT 0, is_sample TINYINT(1) DEFAULT 0, views INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status), INDEX(owner_id),
  FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES business_categories(id));
CREATE TABLE business_locations(business_id INT PRIMARY KEY, address VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL, province VARCHAR(100) NOT NULL, lat DECIMAL(10,7) NOT NULL, lng DECIMAL(10,7) NOT NULL, INDEX(lat,lng), INDEX(city), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE business_hours(id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, day TINYINT NOT NULL, opens TIME, closes TIME, is_closed TINYINT(1) DEFAULT 0, UNIQUE(business_id,day), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE business_images(id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, path VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, category_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, price DECIMAL(10,2) NOT NULL, stock INT DEFAULT 0, available TINYINT(1) DEFAULT 1, views INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(business_id), INDEX(category_id),
  FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES product_categories(id));
CREATE TABLE product_images(id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, path VARCHAR(255) NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, user_id INT NOT NULL, rating TINYINT NOT NULL, comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(business_id,user_id),
  FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE favorites(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, business_id INT NULL, product_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,business_id), UNIQUE(user_id,product_id),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE inquiries(id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, product_id INT NULL, user_id INT NOT NULL, message TEXT NOT NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(255) NOT NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,is_read), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE reports(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, business_id INT NULL, product_id INT NULL, reason VARCHAR(500) NOT NULL, status ENUM('open','resolved') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
